def main():
    input = sys.stdin.readline
    N, K = map(int, input().split())
    M = N * K
    adj = [[] for _ in range(M + 1)]
    for _ in range(M - 1):
        u, v = map(int, input().split())
        adj[u].append(v)
        adj[v].append(u)

    if K == 1:
        print("Yes")
        return

    # Root the tree at 1
    parent = [0] * (M + 1)
    order = []
    stack = [1]
    parent[1] = -1
    while stack:
        u = stack.pop()
        order.append(u)
        for w in adj[u]:
            if w != parent[u]:
                parent[w] = u
                stack.append(w)

    # dp[u] = length of the dangling path starting at u going upward
    # (0 means u is fully matched within its subtree)
    dp = [0] * (M + 1)
    ok = True
    for u in reversed(order):
        cnt = [0] * K  # cnt[r] = number of children with dp value r (1..K-1)
        for w in adj[u]:
            if parent[w] == u:
                r = dp[w]
                if r == 0:
                    continue
                cnt[r] += 1

        # Greedy matching: pair smallest with largest
        l, r = 1, K - 1
        while l < r:
            while l < r and cnt[l] == 0:
                l += 1
            while l < r and cnt[r] == 0:
                r -= 1
            if l >= r:
                break
            if l + r < K:
                # pair them
                take = min(cnt[l], cnt[r])
                cnt[l] -= take
                cnt[r] -= take
            else:
                # cannot pair
                ok = False
                break
        if not ok:
            break

        # Handle remaining at l == r
        if l == r:
            if 2 * l < K:
                if cnt[l] % 2 == 1:
                    # one leftover becomes dangling
                    dp[u] = l + 1
                else:
                    dp[u] = 0
            else:
                if cnt[l] > 0:
                    ok = False
                    break
                dp[u] = 0
        else:
            # all matched
            dp[u] = 0

        # If dp[u] == 0, u itself starts a new dangling path of length 1
        if dp[u] == 0:
            dp[u] = 1

    if not ok or dp[1] != 0:
        print("No")
    else:
        print("Yes")

