class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        # Map each boundary point to its distance along the perimeter starting from (0,0)
        # Order: (0,0) -> (side,0) -> (side,side) -> (0,side) -> (0,0)
        def pos(p):
            x, y = p
            if y == 0:
                return x
            if x == side:
                return side + y
            if y == side:
                return 3 * side - x
            return 4 * side - y

        P = 4 * side
        arr = sorted(pos(p) for p in points)
        n = len(arr)

        # Check if we can select at least k points with pairwise circular distance >= d
        def ok(d):
            # Try each point as the first selected point
            for start in range(n):
                cnt = 1
                last = arr[start]
                # Greedily pick the next point at least d away along the circle
                for j in range(start + 1, start + n):
                    cur = arr[j % n] + (P if j >= n else 0)
                    if cur - last >= d:
                        cnt += 1
                        last = cur
                        if cnt == k:
                            # Ensure the last and first are also at least d apart on the circle
                            if arr[start] + P - last >= d:
                                return True
                            break
            return False

        lo, hi = 1, P // k
        ans = 0
        while lo <= hi:
            mid = (lo + hi) // 2
            if ok(mid):
                ans = mid
                lo = mid + 1
            else:
                hi = mid - 1
        return ans

