class Solution:
    def minCostGoodCaption(self, caption: str) -> str:
        n = len(caption)
        if n < 3:
            return ""

        # Precompute cost to change each character to each letter
        cost = [[0] * 26 for _ in range(n)]
        for i in range(n):
            orig = ord(caption[i]) - ord('a')
            for j in range(26):
                cost[i][j] = abs(orig - j)

        # dp[i][j] = (min_cost, path) for prefix ending at i with last char j
        # We need to track the actual string for lexicographic comparison
        # Use DP with path reconstruction

        # dp[i][j] = min cost to make caption[0..i] good with caption[i] = j
        # parent[i][j] = previous character choice
        dp = [[float('inf')] * 26 for _ in range(n)]
        parent = [[-1] * 26 for _ in range(n)]

        # Initialize: first group must be at least 3
        for j in range(26):
            dp[2][j] = cost[0][j] + cost[1][j] + cost[2][j]
            parent[2][j] = -1  # Start of string

        # Fill DP
        for i in range(3, n):
            for j in range(26):
                # Option 1: extend current group (previous char also j)
                if dp[i-1][j] != float('inf'):
                    new_cost = dp[i-1][j] + cost[i][j]
                    if new_cost < dp[i][j]:
                        dp[i][j] = new_cost
                        parent[i][j] = j

                # Option 2: start new group (need at least 3 of previous char k != j)
                for k in range(26):
                    if k == j:
                        continue
                    if i >= 3 and dp[i-3][k] != float('inf'):
                        new_cost = dp[i-3][k] + cost[i-2][j] + cost[i-1][j] + cost[i][j]
                        if new_cost < dp[i][j]:
                            dp[i][j] = new_cost
                            parent[i][j] = k

        # Find minimum cost at position n-1
        min_cost = float('inf')
        for j in range(26):
            min_cost = min(min_cost, dp[n-1][j])

        if min_cost == float('inf'):
            return ""

        # Among all endings with min_cost, find lexicographically smallest result
        # We need to reconstruct and compare
        best_result = None

        for j in range(26):
            if dp[n-1][j] == min_cost:
                # Reconstruct
                result = []
                pos = n - 1
                curr = j

                while pos >= 0:
                    result.append(chr(curr + ord('a')))
                    if pos == 2:
                        break
                    prev = parent[pos][curr]
                    if prev == curr:
                        pos -= 1
                    else:
                        # Jump back 3 positions
                        result.append(chr(curr + ord('a')))
                        result.append(chr(curr + ord('a')))
                        pos -= 3
                        curr = prev

                result.reverse()
                result_str = ''.join(result)

                if best_result is None or result_str < best_result:
                    best_result = result_str

        return best_result if best_result else ""

