def main():
    data = sys.stdin.read().split()
    if not data:
        return
    N = int(data[0]); P = int(data[1])
    half = N // 2
    maxM = N * (N - 1) // 2

    # Precompute binomial coefficients modulo P for n up to maxM
    C = [[0] * (maxM + 1) for _ in range(maxM + 1)]
    for n in range(maxM + 1):
        C[n][0] = C[n][n] = 1 % P
        for k in range(1, n):
            C[n][k] = (C[n-1][k-1] + C[n-1][k]) % P

    # Precompute powers of 2 modulo P
    pow2 = [1] * (maxM + 1)
    for i in range(1, maxM + 1):
        pow2[i] = (pow2[i-1] * 2) % P

    # Total connected labeled graphs by number of edges
    total_conn = [0] * (maxM + 1)
    for n in range(1, N + 1):
        max_edges_n = n * (n - 1) // 2
        f = [0] * (max_edges_n + 1)
        for m in range(max_edges_n + 1):
            f[m] = C[max_edges_n][m]
        for k in range(1, n):
            max_edges_k = k * (k - 1) // 2
            binom_n1_k1 = C[n-1][k-1]
            max_edges_nk = (n - k) * (n - k - 1) // 2
            for m_k in range(max_edges_k + 1):
                fk = f[m_k]
                if fk == 0:
                    continue
                coeff = binom_n1_k1 * fk % P
                for m_rest in range(max_edges_nk + 1):
                    f[m_k + m_rest] = (f[m_k + m_rest] - coeff * C[max_edges_nk][m_rest]) % P
        if n == N:
            for m in range(max_edges_n + 1):
                total_conn[m] = f[m] % P

    # Bipartite connected graphs with parts of size half and half, with vertex 1 in first part
    bip_conn = [0] * (maxM + 1)
    max_edges_bip = half * half
    f = [0] * (max_edges_bip + 1)
    for m in range(max_edges_bip + 1):
        f[m] = C[max_edges_bip][m]
    for k in range(1, half):
        l = half - k
        max_edges_kl = k * l
        binom = C[half-1][k-1] * C[half][l] % P
        for m_kl in range(max_edges_kl + 1):
            fk = f[m_kl]
            if fk == 0:
                continue
            coeff = binom * fk % P
            max_edges_rest = (half - k) * (half - l)
            for m_rest in range(max_edges_rest + 1):
                f[m_kl + m_rest] = (f[m_kl + m_rest] - coeff * C[max_edges_rest][m_rest]) % P
    for m in range(max_edges_bip + 1):
        bip_conn[m] = f[m] % P

    # Answer for each M
    ans = [0] * (maxM + 1)
    for m in range(maxM + 1):
        total = 0
        max_j = min(m, max_edges_bip)
        for j in range(max_j + 1):
            b = bip_conn[j]
            if b == 0:
                continue
            rem = m - j
            max_edges_rem = half * (half - 1)
            if rem > max_edges_rem:
                continue
            term = b * pow2[max_edges_rem - rem] % P * C[max_edges_rem][rem] % P
            total = (total + term) % P
        ans[m] = (2 * total) % P
        if m == maxM:
            ans[m] = total_conn[m]

    # Output for M = N-1 to maxM
    out = []
    for m in range(N - 1, maxM + 1):
        out.append(str(ans[m] % P))
    print(' '.join(out))

