class Solution:
    def maxSubarraySum(self, nums: List[int]) -> int:
        n = len(nums)

        # Standard Kadane's algorithm for the original array
        max_ending_here = max_so_far = nums[0]
        for i in range(1, n):
            max_ending_here = max(nums[i], max_ending_here + nums[i])
            max_so_far = max(max_so_far, max_ending_here)

        # Group indices by value
        value_indices = defaultdict(list)
        for i, num in enumerate(nums):
            value_indices[num].append(i)

        # For each unique value, compute max subarray sum after removing all occurrences
        for x, indices in value_indices.items():
            if len(indices) == n:
                continue  # Cannot remove all elements

            # Compute max subarray sum excluding indices in 'indices'
            removed = set(indices)
            current_sum = 0
            local_max = float('-inf')

            for i in range(n):
                if i in removed:
                    current_sum = 0
                else:
                    current_sum = max(nums[i], current_sum + nums[i])
                    local_max = max(local_max, current_sum)

            max_so_far = max(max_so_far, local_max)

        return max_so_far

