class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)

        def can_achieve(max_len: int) -> bool:
            # Try both starting characters
            for start_char in '01':
                ops = 0
                i = 0
                while i < n:
                    expected = start_char if i % 2 == 0 else ('1' if start_char == '0' else '0')
                    if s[i] != expected:
                        ops += 1
                        if ops > numOps:
                            break
                    i += 1
                if ops <= numOps:
                    return True

            # For max_len >= 2, we need to check if we can break all runs
            # to be at most max_len
            if max_len >= 2:
                # Find all runs in original string
                runs = []
                i = 0
                while i < n:
                    j = i
                    while j < n and s[j] == s[i]:
                        j += 1
                    runs.append((s[i], j - i))
                    i = j

                # For each run, calculate minimum flips needed to break it
                # into segments of length <= max_len
                total_ops = 0
                for char, length in runs:
                    if length > max_len:
                        # Need to place flips to break the run
                        # Minimum flips = floor(length / (max_len + 1))
                        total_ops += length // (max_len + 1)
                        if total_ops > numOps:
                            return False

                if total_ops <= numOps:
                    return True

            return False

        # Binary search on answer
        left, right = 1, n
        answer = n

        while left <= right:
            mid = (left + right) // 2
            if can_achieve(mid):
                answer = mid
                right = mid - 1
            else:
                left = mid + 1

        return answer

