import math
from typing import List

class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        # DSU over the values 1..threshold
        parent = list(range(threshold + 1))
        rank = [0] * (threshold + 1)

        def find(x: int) -> int:
            # iterative path compression
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a: int, b: int) -> None:
            ra, rb = find(a), find(b)
            if ra == rb:
                return
            if rank[ra] < rank[rb]:
                ra, rb = rb, ra
            parent[rb] = ra
            if rank[ra] == rank[rb]:
                rank[ra] += 1

        # For each possible gcd g, connect all numbers <= threshold that are multiples of g.
        # Any two such numbers have lcm <= threshold.
        for g in range(1, threshold + 1):
            first = -1
            # step through multiples of g
            for m in range(g, threshold + 1, g):
                if first == -1:
                    first = m
                else:
                    union(first, m)

        # Count components:
        # - numbers > threshold are always isolated
        # - numbers <= threshold share the component of their value
        comps = set()
        ans = 0
        for x in nums:
            if x > threshold:
                ans += 1
            else:
                r = find(x)
                if r not in comps:
                    comps.add(r)
                    ans += 1
        return ans
